import { Component, NgModule, input } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-price-tag',
  standalone: false,
  template: `<span>{{ amount() | currency: 'EGP' }}</span>`,
})
export class PriceTag {
  readonly amount = input.required<number>();
}

@NgModule({
  declarations: [PriceTag],
  imports: [CommonModule],
  exports: [PriceTag],
})
export class SharedModule {} // soon declares everything

@Component({
  selector: 'app-cart',
  imports: [SharedModule], // which parts does Cart use? Can't tell
  template: `<app-price-tag [amount]="200" />`,
})
export class Cart {}

import { Component, input } from '@angular/core';
import { CurrencyPipe } from '@angular/common';

@Component({
  selector: 'app-price-tag',
  imports: [CurrencyPipe],
  template: `<span>{{ amount() | currency: 'EGP' }}</span>`,
})
export class PriceTag {
  readonly amount = input.required<number>();
}

@Component({
  selector: 'app-cart',
  imports: [PriceTag], // the template's dependencies, in one place
  template: `<app-price-tag [amount]="200" />`,
})
export class Cart {}

